
	// ----------------------------------------------------------------
	// Nuevas variables para fondos (pega aquí los base64 completos, con el prefijo "data:image/...")
	const fondoABase64 = "data:image/png;base64,"; // Fondo para el frente del carnet (contiene logo/firma si corresponde)
	const FondoBbase64 = "data:image/png;base64,";
	const FondoFirmaBase64 = "data:image/png;base64,";
    const LogoBase64 = "data:image/png;base64, "; // Aquí va el fondo del carnet en base64 si se desea

// ----------------------------------------------------------------

// Variables globales
let userData = null;
let isInitialized = false;
let backgroundsReady = false;

// Función para inicializar credenciales.js (para uso en credenciales.html)
function initCredenciales() {
    if (isInitialized) return;
    isInitialized = true;

    const user = JSON.parse(localStorage.getItem('user'));
    if (!user) {
        window.location.href = 'index.html';
        return;
    }

    const downloadBtn = document.getElementById('download-btn');
    if (downloadBtn) downloadBtn.disabled = true;

    // Usar el nuevo endpoint que es accesible por todos los usuarios
    fetch(`api/user-data.php?id=${user.id}`, {
        credentials: 'include'
    })
    .then(res => {
        if (!res.ok) {
            throw new Error(`HTTP error! status: ${res.status}`);
        }
        return res.json();
    })
    .then(data => {
        if (!data.success) {
            throw new Error(data.error || 'No se pudo obtener la información del usuario.');
        }
        userData = data.data;
        document.getElementById('username').textContent = userData.nombre;
        
        const generateCardBtn = document.getElementById('generate-card');
        const generateSignatureBtn = document.getElementById('generate-signature');
        
        if (generateCardBtn) generateCardBtn.disabled = false;
        if (generateSignatureBtn) generateSignatureBtn.disabled = false;
        if (downloadBtn) downloadBtn.disabled = true;
    })
    .catch(error => {
        console.error('Error:', error);
        showErrorToast('Error al obtener datos del usuario: ' + error.message);
        setTimeout(() => {
            window.location.href = 'index.html';
        }, 2000);
    });

    // Configurar eventos de los botones
    const generateCardBtn = document.getElementById('generate-card');
    const generateSignatureBtn = document.getElementById('generate-signature');
    
    if (generateCardBtn) {
        generateCardBtn.disabled = true;
        generateCardBtn.addEventListener('click', function() {
            if (!userData) return;
            generateCredential('card');
        });
    }

    if (generateSignatureBtn) {
        generateSignatureBtn.disabled = true;
        generateSignatureBtn.addEventListener('click', function() {
            if (!userData) return;
            generateCredential('signature');
        });
    }

    if (downloadBtn) {
        downloadBtn.disabled = true;
        downloadBtn.addEventListener('click', function() {
            downloadCredential();
        });
    }
}

