// Función para descargar credencial/firma
function downloadCredential(externalUserData = null) {
    const targetUserData = externalUserData || userData;
    const isUsuariosPage = !!externalUserData;
    
    const previewContent = isUsuariosPage ? 
        document.getElementById('preview-content-usuarios') : 
        document.getElementById('preview-content');

    if (!previewContent) {
        showErrorToast('No se encontró el contenido para descargar');
        return;
    }

    if (previewContent.querySelector('#cred-card-front')) {
        // Descarga de carnets
        const frontTarget = previewContent.querySelector('#cred-card-front');
        const backTarget = previewContent.querySelector('#cred-card-back');
        if (!frontTarget || !backTarget) {
            showErrorToast('No se encontraron las tarjetas para descargar');
            return;
        }

        downloadSingleCard(frontTarget, "Credencial_Frente_" + (targetUserData.nombre || "usuario") + ".png", function() {
            setTimeout(() => {
                downloadSingleCard(backTarget, "Credencial_Reverso_" + (targetUserData.nombre || "usuario") + ".png");
            }, 800);
        });
    } else {
        // Descarga de firma
        downloadSignature(targetUserData);
    }
}

// Función para descargar una sola tarjeta (frente o reverso)
function downloadSingleCard(element, filename, callback) {
    const cardWidth = 320;
    const cardHeight = 510;
    const scale = 3;

    // Forzar estilos compatibles antes de capturar
    const images = element.getElementsByTagName('img');
    const originalStyles = [];
    
    // Guardar estilos originales y aplicar estilos compatibles
    for (let i = 0; i < images.length; i++) {
        const img = images[i];
        originalStyles.push({
            element: img,
            style: img.getAttribute('style') || ''
        });
        
        // Aplicar estilos más compatibles para html2canvas
        img.style.maxWidth = 'none';
        img.style.objectFit = 'contain';
        img.style.width = 'auto';
        img.style.height = '100%';
    }

    // Esperar a que todas las imágenes se carguen
    Promise.all(
        Array.from(images).map(img => {
            if (img.complete) return Promise.resolve();
            return new Promise(resolve => {
                img.addEventListener('load', resolve);
                img.addEventListener('error', resolve);
            });
        })
    ).then(() => {
        return new Promise(resolve => setTimeout(resolve, 100));
    }).then(() => {
        const options = {
            useCORS: true,
            allowTaint: false,
            backgroundColor: null,
            scale: scale,
            width: cardWidth,
            height: cardHeight,
            x: 0,
            y: 0,
            scrollX: 0,
            scrollY: 0,
            onclone: function(clonedDoc) {
                // Asegurar que los estilos compatibles se apliquen también en el clone
                const clonedImages = clonedDoc.querySelectorAll('img');
                clonedImages.forEach(img => {
                    img.style.maxWidth = 'none';
                    img.style.objectFit = 'contain';
                    img.style.width = 'auto';
                    img.style.height = '100%';
                });
            }
        };

        return html2canvas(element, options);
    }).then(canvas => {
        // Restaurar estilos originales
        originalStyles.forEach(item => {
            item.element.setAttribute('style', item.style);
        });

        // Crear canvas final manteniendo proporciones exactas
        const finalCanvas = document.createElement('canvas');
        finalCanvas.width = cardWidth * 2;
        finalCanvas.height = cardHeight * 2;
        const ctx = finalCanvas.getContext('2d');
        
        // Dibujar manteniendo proporciones
        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = 'high';
        
        // Calcular dimensiones para mantener relación de aspecto
        const ratio = Math.min(finalCanvas.width / canvas.width, finalCanvas.height / canvas.height);
        const newWidth = canvas.width * ratio;
        const newHeight = canvas.height * ratio;
        const x = (finalCanvas.width - newWidth) / 2;
        const y = (finalCanvas.height - newHeight) / 2;
        
        ctx.drawImage(canvas, x, y, newWidth, newHeight);
        
        const link = document.createElement('a');
        link.download = filename;
        link.href = finalCanvas.toDataURL('image/png', 1.0);
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        
        if (callback) callback();
    }).catch(error => {
        // Restaurar estilos originales incluso en caso de error
        originalStyles.forEach(item => {
            item.element.setAttribute('style', item.style);
        });
        
        console.error('Error al generar la imagen:', error);
        showErrorToast('Error al descargar: ' + error.message);
    });
}

// Función para descargar firma - VERSIÓN SIMPLIFICADA
function downloadSignature(externalUserData = null) {
    const targetUserData = externalUserData || userData;
    
    // Buscar el elemento de la firma de manera más amplia
    let target = document.getElementById('cred-signature');
    
    if (!target) {
        // Si no se encuentra por ID, buscar en los contenedores de preview
        const previewContent = document.getElementById('preview-content') || 
                              document.getElementById('preview-content-usuarios');
        if (previewContent) {
            target = previewContent.querySelector('#cred-signature');
        }
    }
    
    if (!target) {
        console.error('Elemento #cred-signature no encontrado');
        showErrorToast('No se encontró la firma para descargar. Genere la firma primero.');
        return;
    }

    console.log('Elemento firma encontrado:', target);

    // Clonar el elemento para no afectar el original
    const clone = target.cloneNode(true);
    clone.style.position = 'fixed';
    clone.style.left = '0';
    clone.style.top = '0';
    clone.style.zIndex = '9999';
    clone.style.width = '450px';
    clone.style.height = '105px';
    clone.style.overflow = 'hidden';
    document.body.appendChild(clone);

    setTimeout(() => {
        html2canvas(clone, {
            scale: 3,
            useCORS: true,
            allowTaint: false,
            backgroundColor: null,
            width: 450,
            height: 105
        }).then(canvas => {
            document.body.removeChild(clone);
            
            const link = document.createElement('a');
            link.download = "Firma_" + (targetUserData.nombre || "usuario") + ".png";
            link.href = canvas.toDataURL('image/png', 1.0);
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        }).catch(error => {
            document.body.removeChild(clone);
            console.error('Error al generar la firma:', error);
            showErrorToast('Error al descargar firma: ' + error.message);
        });
    }, 500);
}

// Funciones auxiliares
function formatDateDMY(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    if (isNaN(date.getTime())) return '-';
    const day = String(date.getDate()).padStart(2, '0');
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const year = date.getFullYear();
    return `${day}/${month}/${year}`;
}

function ensureQRCodeLibraryLoaded(callback) {
    if (window.QRCode) {
        callback();
        return;
    }
    const existing = document.querySelector('script[src*="qrcode.min.js"]');
    if (existing) {
        existing.addEventListener('load', callback);
        return;
    }
    const script = document.createElement('script');
    script.src = "https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js";
    script.onload = callback;
    document.head.appendChild(script);
}

function preloadBackgrounds(frontBase64, backBase64, cb) {
    const toLoad = [];
    if (frontBase64) toLoad.push(frontBase64);
    if (backBase64) toLoad.push(backBase64);
    if (toLoad.length === 0) {
        backgroundsReady = true;
        if (cb) cb();
        return;
    }
    let loaded = 0;
    toLoad.forEach(src => {
        const img = new Image();
        img.onload = img.onerror = function() {
            loaded++;
            if (loaded === toLoad.length) {
                backgroundsReady = true;
                if (cb) cb();
            }
        };
        img.src = src;
    });
}

function waitForElementsReady(type, callback) {
    const isUsuariosPage = !!document.getElementById('preview-content-usuarios');
    let previewContent = isUsuariosPage ? 
        document.getElementById('preview-content-usuarios') : 
        document.getElementById('preview-content');
    
    // Si no encontramos el contenedor específico, buscar en el documento completo
    if (!previewContent) {
        previewContent = document.createElement('div'); // Elemento dummy para evitar errores
    }
        
    const check = () => {
        const imgs = document.querySelectorAll('img');
        let allLoaded = true;
        imgs.forEach(img => {
            if (!img.complete || (img.naturalWidth === 0 && img.src)) allLoaded = false;
        });

        let qrReady = true;
        if (type === 'card') {
            const qrDiv = document.getElementById('qrcode-preview');
            if (!qrDiv) qrReady = false;
            else {
                qrReady = !!(qrDiv.querySelector('canvas') || qrDiv.querySelector('img'));
            }
        }

        if (allLoaded && qrReady && backgroundsReady) {
            callback();
        } else {
            setTimeout(check, 250);
        }
    };
    check();
}

// Funciones de notificación
function showErrorToast(message) {
    if (typeof Swal !== 'undefined') {
        Swal.fire({
            toast: true,
            position: 'top-end',
            icon: 'error',
            title: message,
            showConfirmButton: false,
            timer: 4000,
            timerProgressBar: true
        });
    } else {
        alert('Error: ' + message);
    }
}

function showSuccessToast(message) {
    if (typeof Swal !== 'undefined') {
        Swal.fire({
            toast: true,
            position: 'top-end',
            icon: 'success',
            title: message,
            showConfirmButton: false,
            timer: 2000,
            timerProgressBar: true
        });
    } else {
        alert('Éxito: ' + message);
    }
}

// Inicialización automática solo para credenciales.html
if (document.getElementById('generate-card') && document.getElementById('generate-signature')) {
    document.addEventListener('DOMContentLoaded', initCredenciales);
}

// Exportar funciones para uso externo
window.generateCredential = generateCredential;
window.downloadCredential = downloadCredential;
window.initCredenciales = initCredenciales;
window.showErrorToast = showErrorToast;
window.showSuccessToast = showSuccessToast;